71:    let directory = std::env::var_os("OP_BLOB_CATALOG_DIR")
72:        .map(std::path::PathBuf::from)
73:        .unwrap_or_else(|| op_blob::catalog::DEFAULT_SHM_DIR.into());
74:    op_blob::catalog::read_plugin_state_store_schema(&directory, plugin_id)
75:        .with_context(|| format!("missing or invalid sealed {plugin_id} schema in {}", directory.display()))
76:}
