116:fn capture() -> Result<Captured> {
117:    let binary = super::tched_router_paths::binary()?;
118:    let manifest = super::tched_router_paths::manifest()?;
119:    let config_dir = super::tched_router_paths::config_dir()?;
120:    let (capture_binary, capture_manifest) = super::tched_router_paths::capture_paths()?;
121:    let manifest_sha256 = sha256_file(&capture_manifest)?;
122:    let descriptor: Value = serde_json::from_reader(File::open(&capture_manifest)?)?;
123:    let binary_sha256 = sha256_file(&capture_binary)?;
124:    let version = manifest_version(&descriptor, &binary_sha256)?;
125:    let bare_version = version.strip_prefix("threetched ")
126:        .expect("manifest_version prefixes the bare version").to_owned();
127:    let surface = ThreetchedSurface::capture_with_config(&capture_binary, &config_dir)?;
128:    ensure!(surface.binary_sha256() == binary_sha256, "threetched executable changed during capture");
129:    ensure!(surface.version() == Some(version.as_str()), "threetched version differs from its manifest");
130:    ensure!(sha256_file(&capture_manifest)? == manifest_sha256, "threetched manifest changed during capture");
131:    let state = ThreetchedState {
132:        binary: path_text(&binary)?,
133:        manifest: path_text(&manifest)?,
134:        config_dir: path_text(&config_dir)?,
135:        binary_sha256: surface.binary_sha256().to_owned(),
136:        manifest_sha256,
137:        surface: serde_json::to_value(surface.snapshot())?,
138:    };
139:    Ok(Captured { state, surface, version: bare_version })
140:}
