157:fn command_policy(method: &str) -> (String, String) {
158:    // Exact method bytes keep dotted/hyphenated CLI names distinct. This is a
159:    // policy identifier, not an inferred CLI type or a hardcoded method table.
160:    let key = format!("c{:x}", Sha256::digest(method.as_bytes()));
161:    (
162:        format!("cap.software.threetched.call.{key}@v1"),
163:        format!("mut.software.threetched.call.{key}@v1"),
164:    )
