91:fn sha256_file(path: &Path) -> Result<String> {
92:    let mut file = File::open(path).with_context(|| format!("open {}", path.display()))?;
93:    let mut hasher = Sha256::new();
94:    let mut buffer = [0u8; 64 * 1024];
95:    loop {
96:        let count = file.read(&mut buffer)?;
97:        if count == 0 {
98:            break;
99:        }
100:        hasher.update(&buffer[..count]);
101:    }
102:    Ok(format!("{:x}", hasher.finalize()))
103:}
