4405:                        self,
4406:                        proof,
4407:                        actor_id,
4408:                        session_id,
4409:                        session_genesis,
4410:                        true,
4411:                    )
4412:                    .await?;
4413:                }
4414:                let args = serde_json::to_value(&parsed_value)?;
4415:                let sealed_source = pinned.schema.example.as_ref()
4416:                    .context("sealed threetched feature source descriptor missing")?;
4417:                let source_value = serde_json::to_value(sealed_source)?;
4418:                let source = serde_json::from_value(source_value)?;
4419:                let result = op_plugins::state_plugins::threetched::dispatch(
4420:                    method, &args, &source, operation.clone(),
4421:                ).await?;
4422:                let declaration = pinned.schema.methods.get(method)
4423:                    .context("pinned threetched feature method is absent")?;
4424:                crate::method_contract_admission::validate_admitted_output(
